<?php
declare(strict_types=1);namespace App\Imperium\Runtime\Foundry;use App\Bootstrap\CanonicalJson;use Symfony\Component\DependencyInjection\Attribute\Autowire;
final readonly class SubordinateConstructionCaseService
{private string $acceptanceDirectory;private string $officeRoot;private string $caseDirectory;public function __construct(#[Autowire('%kernel.project_dir%')]string $projectDir){$this->acceptanceDirectory=$projectDir.'/var/imperium/offices/foundry/subordinate-construction-acceptances';$this->officeRoot=$projectDir.'/var/imperium/offices';$this->caseDirectory=$projectDir.'/var/imperium/offices/foundry/subordinate-construction-cases';}
public function open(string $acceptanceId):array
{if(!preg_match('/^foundry-subordinate-acceptance-[a-f0-9]{20}$/',$acceptanceId))throw new \InvalidArgumentException('F100_SUBORDINATE_ACCEPTANCE_ID_INVALID');$a=$this->read($this->acceptanceDirectory.'/'.$acceptanceId.'.json','F101_SUBORDINATE_ACCEPTANCE_ABSENT');$refs=$a['authorized_resolutions']??null;if(!$this->digestMatches($a)||$acceptanceId!==($a['acceptance_id']??null)||'imperium.foundry-subordinate-construction-authorization-acceptance/v1'!==($a['schema']??null)||'foundry.artificer'!==($a['actor']['seat']??null)||'ACCEPTED_FOR_EXACT_SUBORDINATE_CONSTRUCTION'!==($a['disposition']??null)||true!==($a['recipient_acceptance']??null)||true!==($a['construction_authority']??null)||true!==($a['construction_authority_exercisable']??null)||true===($a['persona_selection_authority']??null)||true===($a['profile_approval_authority']??null)||true===($a['spawning_authority']??null)||true===($a['seat_binding_authority']??null)||true===($a['execution_authority']??null)||!is_array($refs)||[]===$refs)throw new \RuntimeException('F102_SUBORDINATE_ACCEPTANCE_INVALID');
$cases=[];$seen=[];foreach($refs as$index=>$ref){$id=is_array($ref)?($ref['resolution_id']??null):null;$office=is_array($ref)?($ref['office']??null):null;if(!is_string($id)||!in_array($office,['hagiography','studium'],true)||isset($seen[$id]))throw new \RuntimeException('F103_SUBORDINATE_RESOLUTION_SET_INVALID');$r=$this->read($this->officeRoot.'/'.$office.'/subordinate-resolutions/'.$id.'.json','F104_SUBORDINATE_RESOLUTION_ABSENT');if(!$this->digestMatches($r)||'imperium.authorship-subordinate-resolution/v1'!==($r['schema']??null)||($ref['record_digest']??null)!==($r['record_digest']??null)||($a['instance_id']??null)!==($r['instance_id']??null)||$office!==($r['office']??null)||($ref['acceptance_id']??null)!==($r['acceptance_id']??null)||($ref['commission_id']??null)!==($r['commission_id']??null)||($ref['subordinate_staff_class']??null)!==($r['subordinate_staff_class']??null)||CanonicalJson::encode($ref['required_specializations']??null)!==CanonicalJson::encode($r['decision']['required_specializations']??null)||'PENDING_CURIA_SUBORDINATE_CONSTRUCTION_AUTHORIZATION'!==($r['status']??null)||true!==($r['sealed']??null)||true===($r['construction_authority']??null)||true===($r['persona_selection_authority']??null)||true===($r['profile_approval_authority']??null)||true===($r['spawning_authority']??null)||true===($r['seat_binding_authority']??null)||true===($r['execution_authority']??null))throw new \RuntimeException('F105_SUBORDINATE_RESOLUTION_CHANGED');$caseId='subordinate-construction-case-'.substr(hash('sha256',CanonicalJson::encode([$acceptanceId,$a['record_digest'],$index,$id,$r['record_digest']])),0,20);$cases[]=$this->persist($caseId,['schema'=>'imperium.foundry-subordinate-construction-case/v1','case_id'=>$caseId,'instance_id'=>$a['instance_id'],'queue_position'=>$index+1,'office'=>$office,'subordinate_staff_class'=>$r['subordinate_staff_class'],'source_resolution_id'=>$id,'source_resolution_digest'=>$r['record_digest'],'source_acceptance_id'=>$r['acceptance_id'],'source_commission_id'=>$r['commission_id'],'authorization_acceptance_id'=>$acceptanceId,'authorization_acceptance_digest'=>$a['record_digest'],'artificer'=>$a['actor'],'subordinate_requirements'=>$r['decision'],'status'=>'OPEN_PENDING_PERSONA_SPECIFICATION','construction_authority'=>true,'persona_selection_authority'=>false,'profile_approval_authority'=>false,'spawning_authority'=>false,'admission_authority'=>false,'seat_binding_authority'=>false,'execution_authority'=>false]);$seen[$id]=true;}return['acceptance_id'=>$acceptanceId,'artificer'=>$a['actor'],'cases'=>$cases];}
private function read(string $p,string $e):array{if(!is_file($p))throw new \RuntimeException($e);return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}private function digestMatches(array $r):bool{$d=$r['record_digest']??null;unset($r['record_digest']);return is_string($d)&&hash_equals($d,hash('sha256',CanonicalJson::encode($r)));}private function persist(string $id,array $case):array{if(!is_dir($this->caseDirectory)&&!mkdir($this->caseDirectory,0770,true)&&!is_dir($this->caseDirectory))throw new \RuntimeException('Foundry subordinate-construction case directory cannot be created.');$case['record_digest']=hash('sha256',CanonicalJson::encode($case));$p=$this->caseDirectory.'/'.$id.'.json';if(is_file($p)){$old=$this->read($p,'F106_SUBORDINATE_CASE_REPLAY_CONFLICT');if(CanonicalJson::encode($old)!==CanonicalJson::encode($case))throw new \RuntimeException('F106_SUBORDINATE_CASE_REPLAY_CONFLICT');return $old;}$tmp=$p.'.tmp.'.bin2hex(random_bytes(6));if(false===file_put_contents($tmp,json_encode($case,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX)||!rename($tmp,$p)){@unlink($tmp);throw new \RuntimeException('Subordinate construction case cannot be committed atomically.');}return $case;}}
